from pathlib import Path
import copy
import hashlib
import json
import os
import subprocess
import sys

ROOT = Path.cwd().resolve()
LEDGER = ROOT / "knowledge/failure_class_ledger.json"
BACKUP = ROOT / "state/governance/backups/gov2_cycle_a_ledger_before.json"
TEMP = ROOT / "knowledge/.failure_class_ledger.gov2_cycle_a.tmp"
ROLLBACK = ROOT / "knowledge/.failure_class_ledger.gov2_cycle_a.rollback.tmp"

EXPECTED_LEDGER = "9109b44ab3a43e8d615d0da31f2cded440596a38d4f1dfba9998214b4f105e0e"
EXPECTED_HEAD = "39321f5f49717267163b2e7f7ce70b8f98db41de"

OLD = {"G-001","G-002","G-003","G-004","G-005","G-006"}
NEW = {
    "G-007","G-008","G-009","G-010","G-011",
    "G-012","G-013","G-014","G-015"
}

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def fresh_write(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("xb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())

changed = False

try:
    head = subprocess.check_output(
        ["git", "rev-parse", "HEAD"],
        cwd=ROOT,
        text=True,
        encoding="utf-8",
    ).strip()

    if head != EXPECTED_HEAD:
        raise RuntimeError("HEAD_MISMATCH")

    if sha(LEDGER) != EXPECTED_LEDGER:
        raise RuntimeError("LEDGER_SHA_MISMATCH")

    raw = LEDGER.read_bytes()
    data = json.loads(raw.decode("utf-8"))

    if data.get("version") != 4:
        raise RuntimeError("LEDGER_VERSION_MISMATCH")

    original_classes = copy.deepcopy(data.get("classes"))

    if not isinstance(original_classes, list) or len(original_classes) != 15:
        raise RuntimeError("CLASS_COUNT_MISMATCH")

    seen_old = set()
    seen_new = set()

    for item in original_classes:
        aliases = set(item.get("aliases", []))
        old_hit = OLD & aliases
        new_hit = NEW & aliases

        if old_hit:
            if len(old_hit) != 1:
                raise RuntimeError("OLD_ALIAS_COLLISION")
            if item.get("status") != "CLOSED":
                raise RuntimeError("OLD_CLASS_NOT_CLOSED")
            if item.get("closure_evidence", {}).get("ledger_version") != 3:
                raise RuntimeError("OLD_CLOSURE_NOT_STALE_V3")
            seen_old.update(old_hit)

        if new_hit:
            if len(new_hit) != 1:
                raise RuntimeError("NEW_ALIAS_COLLISION")
            if (
                item.get("status") != "OPEN"
                or item.get("closure_evidence") != {}
            ):
                raise RuntimeError("NEW_CLASS_STATE_MISMATCH")
            seen_new.update(new_hit)

    if seen_old != OLD or seen_new != NEW:
        raise RuntimeError("ALIAS_SET_MISMATCH")

    if BACKUP.exists() or TEMP.exists() or ROLLBACK.exists():
        raise RuntimeError("FRESH_MUTATION_PATH_REQUIRED")

    fresh_write(BACKUP, raw)

    if sha(BACKUP) != EXPECTED_LEDGER:
        raise RuntimeError("BACKUP_SHA_MISMATCH")

    data["version"] = 5

    for item in data["classes"]:
        if OLD & set(item.get("aliases", [])):
            item["status"] = "REOPENED"

    fresh_write(
        TEMP,
        (json.dumps(data, ensure_ascii=False, indent=2) + "\n").encode("utf-8"),
    )

    os.replace(TEMP, LEDGER)
    changed = True

    check = json.loads(LEDGER.read_text(encoding="utf-8"))

    if check.get("version") != 5:
        raise RuntimeError("POST_VERSION_MISMATCH")

    if len(check.get("classes", [])) != 15:
        raise RuntimeError("POST_CLASS_COUNT_MISMATCH")

    for before, after in zip(original_classes, check["classes"]):
        aliases = set(before.get("aliases", []))

        if OLD & aliases:
            expected = copy.deepcopy(before)
            expected["status"] = "REOPENED"
            if after != expected:
                raise RuntimeError("G001_G006_UNEXPECTED_CHANGE")
        else:
            if after != before:
                raise RuntimeError("G007_G015_CHANGED")

    print("GOV2_CYCLE_A_MUTATION:PASS")
    print("LEDGER_VERSION=5")
    print("G001_G006_STATUS=REOPENED")
    print("G007_G015_STATUS=OPEN")

except Exception as error:
    if changed:
        try:
            fresh_write(ROLLBACK, BACKUP.read_bytes())
            os.replace(ROLLBACK, LEDGER)

            if sha(LEDGER) != EXPECTED_LEDGER:
                raise RuntimeError("ROLLBACK_SHA_MISMATCH")

            print("ROLLBACK:PASS", file=sys.stderr)

        except Exception as rollback_error:
            print(
                f"ROLLBACK:FAIL:{type(rollback_error).__name__}",
                file=sys.stderr,
            )

    print(
        f"GOV2_CYCLE_A_MUTATION:FAIL:{type(error).__name__}:{error}",
        file=sys.stderr,
    )
    sys.exit(1)

